
-- ============================================================
-- TABLE: release_history
-- PURPOSE:
-- Stores the history of changes detected during release
-- synchronization with external providers.
--
-- Each record represents a change in a specific field of a
-- release, preserving its previous and new values.
-- ============================================================

CREATE TABLE release_history (
    -- Internal identifier generated by PostgreSQL.
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    -- Reference to the release associated with this change.
    release_id BIGINT NOT NULL,

    -- Name of the field that was modified.
    field_changed VARCHAR(50) NOT NULL,

    -- Value stored before the change.
    old_value TEXT,

    -- New value reported by the external provider.
    new_value TEXT,

    -- Date and time when the change was detected.
    changed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_release_history_release
        FOREIGN KEY (release_id)
        REFERENCES releases(id)
        ON DELETE CASCADE
);

-- ============================================================
-- TABLE AND COLUMN DOCUMENTATION
-- ============================================================

COMMENT ON TABLE release_history IS
    'Stores the historical changes detected in release information during synchronization.';

COMMENT ON COLUMN release_history.id IS
    'Internal primary key generated automatically by PostgreSQL.';

COMMENT ON COLUMN release_history.release_id IS
    'Foreign key referencing the release associated with the recorded change.';

COMMENT ON COLUMN release_history.field_changed IS
    'Name of the release field whose value changed.';

COMMENT ON COLUMN release_history.old_value IS
    'Value of the field before the detected change. NULL indicates that no previous value existed.';

COMMENT ON COLUMN release_history.new_value IS
    'New value reported by the external provider. NULL indicates that the previous value was removed.';

COMMENT ON COLUMN release_history.changed_at IS
    'Timestamp indicating when the application detected and recorded the change.';

